import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBarlow = makeLoadFont('BarlowCondensed');

const { fontFamily } = loadBarlow();



export type SupplementAdProps = Record<string, any>;

const SupplementAd: React.FC<SupplementAdProps> = ({
  backgroundColor = "#0b1120",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#ccff00",
  primaryTextColor = "#ffffff",
  bottleBodyColor = "#e5e7eb",
  bottleLidColor = "#1f2937",
  statements = [
    { highlight: "NO", rest: "SCOOP" },
    { highlight: "NO", rest: "SHAKER" },
    { highlight: "NO", rest: "MIXING" },
    { highlight: "NO", rest: "FORGETTING" }
  ],
  bottleTextTop = "CREATINE",
  bottleTextBottom = "PROTEIN",
  iconLabelColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Responsive scaling factor based on a 1080p vertical canvas reference
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const textStartFrame = 10;
  const textStagger = 6;
  const bottleStartFrame = 30;
  const iconStartFrame = 45;
  const iconStagger = 8;

  // Animation values for the central bottle
  const bottleSpr = spring({
    frame: frame - bottleStartFrame,
    fps,
    config: { damping: 14, mass: 1.2 },
  });
  
  const bottleY = interpolate(bottleSpr, [0, 1], [height * 0.5, 0]);
  const bottleScale = interpolate(bottleSpr, [0, 1], [0.8, 1]);
  const bottleOpacity = interpolate(bottleSpr, [0, 0.1, 1], [0, 1, 1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, color: primaryTextColor, overflow: "hidden" }}>
      
      {/* Container to enforce vertical layout within safe zones */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        width: "100%",
        height: "100%",
        paddingTop: height * 0.1,
        paddingBottom: height * 0.05,
      }}>
        
        {/* Top Text Block */}
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start", // Left align the text block internally
          marginBottom: 40 * s,
        }}>
          {statements.map((stmt, i) => {
            const spr = spring({
              frame: frame - textStartFrame - i * textStagger,
              fps,
              config: { damping: 12, mass: 0.8 },
            });
            const itemY = interpolate(spr, [0, 1], [-80 * s, 0]);
            const itemScale = interpolate(spr, [0, 1], [1.2, 1]);
            const itemOpacity = interpolate(spr, [0, 0.2, 1], [0, 1, 1], { extrapolateRight: "clamp" });

            return (
              <div 
                key={i} 
                style={{ 
                  display: "flex", 
                  fontSize: 140 * s, 
                  lineHeight: 0.9, 
                  fontWeight: 900, 
                  fontStyle: "italic", 
                  letterSpacing: -2 * s,
                  textTransform: "uppercase",
                  transform: `translateY(${itemY}px) scale(${itemScale})`,
                  opacity: itemOpacity,
                  transformOrigin: "left center",
                }}
              >
                <span style={{ color: accentColor, marginRight: 24 * s }}>{stmt.highlight}</span>
                <span>{stmt.rest}</span>
              </div>
            );
          })}
        </div>

        {/* Central Graphic & Icons Layout */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "1fr auto 1fr",
          alignItems: "center",
          gap: 30 * s,
          width: "100%",
          flex: 1, // Take remaining space
        }}>
          
          {/* Left Column Icons */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 100 * s, paddingRight: 10 * s }}>
            <FeatureIcon 
              iconType="scoop" 
              label="NO SCOOP" 
              delay={iconStartFrame} 
              accentColor={accentColor} 
              labelColor={iconLabelColor} 
              scale={s} 
              frame={frame} 
              fps={fps} 
            />
            <FeatureIcon 
              iconType="mixing" 
              label="NO MIXING" 
              delay={iconStartFrame + iconStagger * 2} 
              accentColor={accentColor} 
              labelColor={iconLabelColor} 
              scale={s} 
              frame={frame} 
              fps={fps} 
            />
          </div>

          {/* Central Bottle */}
          <div style={{
            position: "relative",
            transform: `translateY(${bottleY}px) scale(${bottleScale})`,
            opacity: bottleOpacity,
            zIndex: 10,
          }}>
             <svg width={300 * s} height={550 * s} viewBox="0 0 200 400" style={{ filter: `drop-shadow(0px ${20*s}px ${30*s}px rgba(0,0,0,0.4))` }}>
                {/* Base */}
                <path d="M 35 340 L 165 340 C 165 385 150 400 100 400 C 50 400 35 385 35 340 Z" fill={accentColor} />
                <rect x="85" y="355" width="30" height="35" rx="15" fill={bottleLidColor} />
                <line x1="100" y1="365" x2="100" y2="380" stroke={accentColor} strokeWidth="4" strokeLinecap="round" />
                
                {/* Main Body */}
                <path d="M 25 100 L 175 100 L 160 340 L 40 340 Z" fill={bottleBodyColor} />
                
                {/* Text on Body (Rotated) */}
                <g transform="translate(85, 300) rotate(-90)">
                    <text x="0" y="0" fontFamily={fontFamily} fontSize="34" fontWeight="900" fontStyle="italic" fill={bottleLidColor} letterSpacing="-1">
                      {bottleTextTop}
                    </text>
                    <text x="0" y="32" fontFamily={fontFamily} fontSize="34" fontWeight="900" fontStyle="italic" fill={accentColor} letterSpacing="-1">
                      {bottleTextBottom}
                    </text>
                </g>

                {/* Lid Collar */}
                <path d="M 15 80 L 185 80 L 180 100 L 20 100 Z" fill={bottleLidColor} />
                <path d="M 25 50 L 175 50 L 175 80 L 25 80 Z" fill={bottleLidColor} />
                
                {/* Lid Top & Spout */}
                <path d="M 40 50 L 40 30 L 110 30 L 120 50 Z" fill={accentColor} />
                <path d="M 110 50 C 110 20 145 20 155 50 Z" fill={bottleLidColor} />
             </svg>
          </div>

          {/* Right Column Icons */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 100 * s, paddingLeft: 10 * s }}>
            <FeatureIcon 
              iconType="shaker" 
              label="NO SHAKER" 
              delay={iconStartFrame + iconStagger} 
              accentColor={accentColor} 
              labelColor={iconLabelColor} 
              scale={s} 
              frame={frame} 
              fps={fps} 
            />
            <FeatureIcon 
              iconType="forgetting" 
              label="NO FORGETTING" 
              delay={iconStartFrame + iconStagger * 3} 
              accentColor={accentColor} 
              labelColor={iconLabelColor} 
              scale={s} 
              frame={frame} 
              fps={fps} 
            />
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

// Sub-component for the "No" Icons
const FeatureIcon: React.FC<{
  iconType: "scoop" | "shaker" | "mixing" | "forgetting";
  label: string;
  delay: number;
  accentColor: string;
  labelColor: string;
  scale: number;
  frame: number;
  fps: number;
}> = ({ iconType, label, delay, accentColor, labelColor, scale, frame, fps }) => {
  
  // Animation springs
  const circleSpr = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  const lineSpr = spring({ frame: frame - delay - 8, fps, config: { damping: 14 } });
  const iconSpr = spring({ frame: frame - delay - 14, fps, config: { damping: 12 } });
  const textSpr = spring({ frame: frame - delay - 20, fps, config: { damping: 14 } });

  // Draw-on math
  const radius = 45;
  const pathLength = 2 * Math.PI * radius;
  const dashoffset = interpolate(circleSpr, [0, 1], [pathLength, 0]);

  // Slash line from (18,18) to (82,82) -> length = ~90.5
  const lineLen = 91;
  const lineOffset = interpolate(lineSpr, [0, 1], [lineLen, 0]);

  // Inner icon pop
  const iconOpacity = interpolate(iconSpr, [0, 0.5, 1], [0, 1, 1], { extrapolateRight: "clamp" });
  const iconScale = interpolate(iconSpr, [0, 1], [0.5, 1]);

  // Label slide up
  const textY = interpolate(textSpr, [0, 1], [20 * scale, 0]);
  const textOpacity = interpolate(textSpr, [0, 0.5, 1], [0, 1, 1], { extrapolateRight: "clamp" });

  const renderInnerIcon = () => {
    switch (iconType) {
      case "scoop":
        return (
          <g stroke="#fff" strokeWidth={4} fill="none" strokeLinecap="round" strokeLinejoin="round">
            <path d="M 25 55 L 50 55 C 50 70, 25 70, 25 55 Z" />
            <path d="M 25 55 Q 37.5 45 50 55" />
            <line x1="50" y1="55" x2="80" y2="40" />
            <line x1="50" y1="55" x2="80" y2="46" />
          </g>
        );
      case "shaker":
        return (
          <g stroke="#fff" strokeWidth={4} fill="none" strokeLinecap="round" strokeLinejoin="round">
            <path d="M 35 30 L 65 30 L 60 80 L 40 80 Z" />
            <path d="M 30 20 L 70 20 L 70 30 L 30 30 Z" />
            <path d="M 45 10 L 55 10 L 55 20 L 45 20 Z" />
          </g>
        );
      case "mixing":
        return (
          <g stroke="#fff" strokeWidth={4} fill="none">
            <ellipse cx="50" cy="50" rx="20" ry="25" />
            <ellipse cx="50" cy="50" rx="8" ry="25" />
            <ellipse cx="50" cy="50" rx="20" ry="25" transform="rotate(60 50 50)" />
            <ellipse cx="50" cy="50" rx="20" ry="25" transform="rotate(-60 50 50)" />
          </g>
        );
      case "forgetting":
        return (
          <g stroke="#fff" strokeWidth={4} fill="none" strokeLinecap="round" strokeLinejoin="round">
             {/* Profile outline */}
             <path d="M 45 85 L 45 70 C 45 60, 30 60, 30 50 C 30 30, 70 25, 75 45 C 80 65, 60 70, 60 85 Z" />
             {/* Brain squiggles inside */}
             <path d="M 40 45 Q 50 35 60 45 Q 65 55 55 60 Q 45 65 40 55 Z" />
             <path d="M 45 50 Q 55 55 65 50" />
          </g>
        );
    }
  };

  // Split label into words for multiline display
  const words = label.split(" ");

  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 15 * scale }}>
      {/* Circle Icon Container */}
      <div style={{ position: "relative", width: 150 * scale, height: 150 * scale }}>
        <svg 
          width="100%" 
          height="100%" 
          viewBox="0 0 100 100" 
          style={{ overflow: "visible" }}
        >
          {/* Outer Circle (draws from top) */}
          <circle 
            cx="50" cy="50" r={radius} 
            stroke={accentColor} 
            strokeWidth={6} 
            fill="none"
            strokeDasharray={pathLength} 
            strokeDashoffset={dashoffset}
            transform="rotate(-90 50 50)" 
          />
          
          {/* Inner Icon */}
          <g style={{ 
            opacity: iconOpacity, 
            transform: `scale(${iconScale})`, 
            transformOrigin: "50% 50%" 
          }}>
            {renderInnerIcon()}
          </g>

          {/* Slash Line */}
          <line 
            x1="18" y1="18" x2="82" y2="82" 
            stroke={accentColor} 
            strokeWidth={6}
            strokeDasharray={lineLen} 
            strokeDashoffset={lineOffset}
            strokeLinecap="round"
          />
        </svg>
      </div>

      {/* Text Label */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        color: labelColor,
        fontSize: 32 * scale,
        fontWeight: 900,
        fontStyle: "italic",
        lineHeight: 1.1,
        textAlign: "center",
        textTransform: "uppercase",
        transform: `translateY(${textY}px)`,
        opacity: textOpacity,
      }}>
        {words.map((w, i) => (
           <span key={i} style={{ color: w === "NO" ? accentColor : labelColor }}>
             {w}
           </span>
        ))}
      </div>
    </div>
  );
};

export default SupplementAd;